#include "stdafx.h"#include "KbdDriver.h"#include <winioctl.h>#include "ioctls.h"#include "LogFile.h"#define DRIVERPATH "\\\\.\\KbdYokogawa"CKbdDriver::CKbdDriver(void)  {  Clear();      }CKbdDriver::~CKbdDriver(void)  {  Close();  }BOOL CKbdDriver::IsOpened()  {  return hdevice != INVALID_HANDLE_VALUE && hdevice0 != INVALID_HANDLE_VALUE;  }void CKbdDriver::Clear()  {  hdevice = INVALID_HANDLE_VALUE;  hdevice0 = INVALID_HANDLE_VALUE;  hThread = NULL;  dwThread = 0;  pOnReadFunc = NULL;  }void CKbdDriver::Close()  {  pOnReadFunc = NULL;  if(hThread != NULL)    {    TerminateThread(hThread, 0);    CloseHandle(hThread);    }  //  if(hdevice0 != INVALID_HANDLE_VALUE)    CloseHandle(hdevice0), hdevice0 = INVALID_HANDLE_VALUE;  if(hdevice != INVALID_HANDLE_VALUE)    CloseHandle(hdevice), hdevice = INVALID_HANDLE_VALUE;  Clear();  }VOID CKbdDriver::Read() {	if(!IsOpened())		return;	BYTE buff[4] = {0};	DWORD Bytes = 0;	while(TRUE)	{		// синхронный ввод		if(ReadFile(hdevice, buff, 4, &Bytes, NULL))		{			CLogFile::Log ("CKbdDriver::Read: Bytes = %d, buff = [%x %x %x %x]", Bytes, buff[0], buff[1], buff[2], buff[3]);			if(pOnReadFunc != NULL)				pOnReadFunc(Bytes, buff);      else        break;		}		else		{			//printf("Error %d in call to ReadFile\n", GetLastError());			break;		}	}}DWORD CKbdDriver::_ReadThread(LPVOID lpParam) {	CKbdDriver* pClass = (CKbdDriver*)lpParam;	if(pClass != NULL)		pClass->Read();	return 0;}BOOL CKbdDriver::SetReadFunction(OnReadFunc* function){	pOnReadFunc = function;	if(hThread == NULL)	{		hThread = ::CreateThread(NULL, 0, (LPTHREAD_START_ROUTINE)CKbdDriver::_ReadThread, (void*)this, 0, &dwThread);		if (hThread == NULL ) 			return FALSE;		//::SetThreadPriority (hThread, THREAD_PRIORITY_HIGHEST);	}	return TRUE;}BOOL CKbdDriver::Open(){	if(IsOpened())		return TRUE;	hdevice = CreateFile(DRIVERPATH, GENERIC_READ | GENERIC_WRITE, FILE_SHARE_READ | FILE_SHARE_WRITE, NULL, OPEN_EXISTING, 		0, NULL);	if (hdevice == INVALID_HANDLE_VALUE)		return FALSE;	hdevice0 = CreateFile(DRIVERPATH, GENERIC_READ | GENERIC_WRITE, FILE_SHARE_READ | FILE_SHARE_WRITE, NULL, OPEN_EXISTING, 		0, NULL);	if (hdevice0 == INVALID_HANDLE_VALUE)		return FALSE;	return TRUE;}BOOL CKbdDriver::Write(BYTE packet[8]){	if(!IsOpened())		return FALSE;	DWORD Bytes = 0;	return DeviceIoControl(hdevice0, IOCTL_CONTROL, packet, 8, NULL, 0, &Bytes, NULL);}